49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
102	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
103	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
104	    }
105	
106	    /**
107	     * Whether more than 80 owners have already been created on {@code registrationDate},
108	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
109	     */
110	    private boolean isBulkSignup(LocalDate registrationDate) {
111	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        LocalDate registrationDate = owner.resolveRegistrationDate();
120	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
121	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
122	        }
123	        if (this.clinicService.existsOwnerWithTelephone(owner.getTelephone())) {
124	            return new ResponseEntity<>(HttpStatus.CONFLICT);
125	        }
126	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getLastName(), owner.getAddress());
131	        if (!sharesHousehold && householdExists) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        if (sharesHousehold && householdExists) {
135	            this.clinicService.assignHousehold(owner);
136	        }
137	        owner.setNamesakeCount(
138	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
139	        this.clinicService.saveOwner(owner);
140	        auditLogger.info("owner created: id={} customerCode={} registrationDate={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
161	        currentOwner.setEmail(ownerFieldsDto.getEmail());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
